import{_ as t,a as o,o as r,a4 as s}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Reporting — Customers","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest-customers-total-customers","title":"Total Customers","description":"New-customer registrations in the window, compared against the previous period, plus an over-time series (previous vs. current) for the chart line.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/customers?type=total-customers&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"customers\\",\\n    \\"type\\": \\"total-customers\\",\\n    \\"dateRange\\": {\\n      \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\",\\n      \\"current\\": \\"10 May 2026 - 09 Jun 2026\\"\\n    },\\n    \\"statistics\\": {\\n      \\"customers\\": { \\"previous\\": 1, \\"current\\": 9, \\"progress\\": 800 },\\n      \\"over_time\\": {\\n        \\"previous\\": [\\n          { \\"label\\": \\"23 Apr\\", \\"total\\": 1 }\\n        ],\\n        \\"current\\": [\\n          { \\"label\\": \\"12 May\\", \\"total\\": 4 },\\n          { \\"label\\": \\"26 May\\", \\"total\\": 5 }\\n        ]\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-customers-customers-traffic","title":"Customers Traffic","description":"Total vs. unique customer visits compared against the previous period, plus an over-time series. Requires visitor/analytics data — on a fresh store these figures are zero or empty.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/customers?type=customers-traffic&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"customers\\",\\n    \\"type\\": \\"customers-traffic\\",\\n    \\"dateRange\\": {\\n      \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\",\\n      \\"current\\": \\"10 May 2026 - 09 Jun 2026\\"\\n    },\\n    \\"statistics\\": {\\n      \\"total\\": { \\"previous\\": 0, \\"current\\": 0, \\"progress\\": 0 },\\n      \\"unique\\": { \\"previous\\": 0, \\"current\\": 0, \\"progress\\": 0 },\\n      \\"over_time\\": {\\n        \\"previous\\": [],\\n        \\"current\\": []\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-customers-customers-with-most-sales","title":"Customers With Most Sales","description":"Top customers ranked by total spend in the window. `statistics` is a flat array; each row carries the customer\'s order count and formatted total. `id` may be null for guest checkouts.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/customers?type=customers-with-most-sales&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"customers\\",\\n    \\"type\\": \\"customers-with-most-sales\\",\\n    \\"dateRange\\": {\\n      \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\",\\n      \\"current\\": \\"10 May 2026 - 09 Jun 2026\\"\\n    },\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 129,\\n        \\"email\\": \\"jane@example.com\\",\\n        \\"full_name\\": \\"Jane Cooper\\",\\n        \\"total\\": \\"4820.0000\\",\\n        \\"orders\\": 6,\\n        \\"progress\\": 152.4,\\n        \\"formatted_total\\": \\"$4,820.00\\"\\n      },\\n      {\\n        \\"id\\": null,\\n        \\"email\\": \\"devon@example.com\\",\\n        \\"full_name\\": \\"Devon Lane\\",\\n        \\"total\\": \\"3150.5000\\",\\n        \\"orders\\": 4,\\n        \\"progress\\": 88.1,\\n        \\"formatted_total\\": \\"$3,150.50\\"\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-customers-customers-with-most-orders","title":"Customers With Most Orders","description":"Top customers ranked by order count in the window. `statistics` is a flat array. `id` may be null for guest checkouts.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/customers?type=customers-with-most-orders&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"customers\\",\\n    \\"type\\": \\"customers-with-most-orders\\",\\n    \\"dateRange\\": {\\n      \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\",\\n      \\"current\\": \\"10 May 2026 - 09 Jun 2026\\"\\n    },\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 142,\\n        \\"email\\": \\"kesh@king.com\\",\\n        \\"full_name\\": \\"Kesh King\\",\\n        \\"orders\\": 10,\\n        \\"progress\\": 233.33\\n      },\\n      {\\n        \\"id\\": 129,\\n        \\"email\\": \\"jane@example.com\\",\\n        \\"full_name\\": \\"Jane Cooper\\",\\n        \\"orders\\": 6,\\n        \\"progress\\": 100\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-customers-customers-with-most-reviews","title":"Customers With Most Reviews","description":"Top customers ranked by number of product reviews left in the window. `statistics` is a flat array. `id` may be null for guest reviews.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/customers?type=customers-with-most-reviews&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"customers\\",\\n    \\"type\\": \\"customers-with-most-reviews\\",\\n    \\"dateRange\\": {\\n      \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\",\\n      \\"current\\": \\"10 May 2026 - 09 Jun 2026\\"\\n    },\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 129,\\n        \\"email\\": \\"jane@example.com\\",\\n        \\"full_name\\": \\"Jane Cooper\\",\\n        \\"reviews\\": 12,\\n        \\"progress\\": 50\\n      },\\n      {\\n        \\"id\\": 142,\\n        \\"email\\": \\"kesh@king.com\\",\\n        \\"full_name\\": \\"Kesh King\\",\\n        \\"reviews\\": 7,\\n        \\"progress\\": 16.67\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-customers-top-customer-groups","title":"Top Customer Groups","description":"Customer groups ranked by total customers (or members) in the window. `statistics` is a flat array of group rows.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/customers?type=top-customer-groups&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"customers\\",\\n    \\"type\\": \\"top-customer-groups\\",\\n    \\"dateRange\\": {\\n      \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\",\\n      \\"current\\": \\"10 May 2026 - 09 Jun 2026\\"\\n    },\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 1,\\n        \\"group_name\\": \\"General\\",\\n        \\"total\\": 142,\\n        \\"progress\\": 18.33\\n      },\\n      {\\n        \\"id\\": 2,\\n        \\"group_name\\": \\"Wholesale\\",\\n        \\"total\\": 23,\\n        \\"progress\\": 4.55\\n      },\\n      {\\n        \\"id\\": 3,\\n        \\"group_name\\": \\"Guest\\",\\n        \\"total\\": 9,\\n        \\"progress\\": -10\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-customers-view","title":"View Details (table form)","description":"The expanded, row-by-row table behind a panel\'s \\"View Details\\" link. Honors the same `type` — here `customers-with-most-sales`. `statistics` carries `columns` + `records`.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/customers/view?type=customers-with-most-sales&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"customers\\",\\n    \\"type\\": \\"customers-with-most-sales\\",\\n    \\"dateRange\\": {\\n      \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\",\\n      \\"current\\": \\"10 May 2026 - 09 Jun 2026\\"\\n    },\\n    \\"statistics\\": {\\n      \\"columns\\": [\\n        { \\"key\\": \\"full_name\\", \\"label\\": \\"Customer\\" },\\n        { \\"key\\": \\"email\\", \\"label\\": \\"Email\\" },\\n        { \\"key\\": \\"formatted_total\\", \\"label\\": \\"Total\\" }\\n      ],\\n      \\"records\\": [\\n        { \\"id\\": 129, \\"email\\": \\"jane@example.com\\", \\"full_name\\": \\"Jane Cooper\\", \\"total\\": \\"4820.0000\\", \\"orders\\": 6, \\"formatted_total\\": \\"$4,820.00\\" },\\n        { \\"id\\": null, \\"email\\": \\"devon@example.com\\", \\"full_name\\": \\"Devon Lane\\", \\"total\\": \\"3150.5000\\", \\"orders\\": 4, \\"formatted_total\\": \\"$3,150.50\\" },\\n        { \\"id\\": 142, \\"email\\": \\"arlene@example.com\\", \\"full_name\\": \\"Arlene McCoy\\", \\"total\\": \\"2940.2500\\", \\"orders\\": 3, \\"formatted_total\\": \\"$2,940.25\\" }\\n      ]\\n    }\\n  }\\n]\\n"},{"id":"rest-customers-export","title":"Export (CSV)","description":"Streams the View Details table as a text/csv attachment (the Export button). Header row is built from the column labels; honors the same `type`. CSV only — any other format returns 422.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/customers/export?type=customers-with-most-sales&format=csv&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  -o customers-report.csv\\n","response":"Customer,Email,Total\\nJane Cooper,jane@example.com,\\"$4,820.00\\"\\nDevon Lane,devon@example.com,\\"$3,150.50\\"\\nArlene McCoy,arlene@example.com,\\"$2,940.25\\"\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/reporting/customers.md","filePath":"api/rest-api/admin/reporting/customers.md","lastUpdated":1783420618000}'),a={name:"api/rest-api/admin/reporting/customers.md"};function n(d,e,c,i,l,u){return r(),o("div",null,e[0]||(e[0]=[s('<h1 id="reporting-—-customers" tabindex="-1">Reporting — Customers <a class="header-anchor" href="#reporting-—-customers" aria-label="Permalink to &quot;Reporting — Customers&quot;">​</a></h1><p>Returns the aggregate statistics that power the Bagisto admin <strong>Reporting → Customers</strong> report — new customers, traffic, top spenders, most orders, most reviews and top customer groups.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Endpoint</strong></td><td><code>GET /api/admin/reporting/customers</code></td></tr><tr><td><strong>Returns</strong></td><td>A JSON <strong>array</strong> with a single element: <code>[ { entity, type, dateRange, statistics } ]</code></td></tr></tbody></table><p>All admin endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p><h2 id="understanding-type-—-the-report-is-six-separate-calls" tabindex="-1">Understanding <code>type</code> — the report is <strong>six</strong> separate calls <a class="header-anchor" href="#understanding-type-—-the-report-is-six-separate-calls" aria-label="Permalink to &quot;Understanding `type` — the report is **six** separate calls&quot;">​</a></h2><p>The Customers report screen is <strong>not one response</strong>. It is assembled from <strong>six independent requests</strong>, one per panel, and each is selected with the <code>?type=</code> query parameter. These six groups are exactly the panels of the admin Reporting → Customers screen — no more, no less.</p><p>So a single call returns <strong>one panel</strong> of the report. To render the full screen, call the endpoint once per <code>type</code> (or only for the panels you need). The <code>statistics</code> payload <strong>changes shape per <code>type</code></strong> — sometimes an object, sometimes a flat array — so always branch on <code>type</code> when consuming it.</p><h3 id="which-type-maps-to-which-panel" tabindex="-1">Which <code>type</code> maps to which panel <a class="header-anchor" href="#which-type-maps-to-which-panel" aria-label="Permalink to &quot;Which `type` maps to which panel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Report panel (admin)</th><th><code>type</code></th><th><code>statistics</code> is</th></tr></thead><tbody><tr><td><strong>Total Customers</strong> chart</td><td><code>total-customers</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Customers Traffic</strong> chart</td><td><code>customers-traffic</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Customers With Most Sales</strong> list</td><td><code>customers-with-most-sales</code></td><td>array</td></tr><tr><td><strong>Customers With Most Orders</strong> list</td><td><code>customers-with-most-orders</code></td><td>array</td></tr><tr><td><strong>Customers With Most Reviews</strong> list</td><td><code>customers-with-most-reviews</code></td><td>array</td></tr><tr><td><strong>Top Customer Groups</strong> list</td><td><code>top-customer-groups</code></td><td>array</td></tr></tbody></table><p><code>total-customers</code> is the default — if you omit <code>?type=</code>, you get the &quot;Total Customers&quot; chart.</p><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>enum</td><td>No</td><td>One of the six values above. Defaults to <code>total-customers</code>. An unknown value returns <strong>400</strong> (<code>invalid-type</code>).</td></tr><tr><td><code>start</code></td><td>date (YYYY-MM-DD)</td><td>No</td><td>Lower bound of the reporting window. Defaults to <strong>30 days ago</strong>.</td></tr><tr><td><code>end</code></td><td>date (YYYY-MM-DD)</td><td>No</td><td>Upper bound. Defaults to <strong>today</strong>.</td></tr><tr><td><code>channel</code></td><td>string</td><td>No</td><td>Channel <strong>code</strong> to scope the figures to a single channel. Defaults to all channels.</td></tr></tbody></table><p><code>start</code> / <code>end</code> drive both the figures and the <code>previous</code> baseline used for each <code>progress</code> percentage — the previous period is the same-length window immediately before <code>start</code>.</p><h2 id="response-envelope" tabindex="-1">Response envelope <a class="header-anchor" href="#response-envelope" aria-label="Permalink to &quot;Response envelope&quot;">​</a></h2><p>The endpoint always returns a <strong>single-element array</strong>: <code>[ { entity, type, dateRange, statistics } ]</code>.</p><ul><li><code>entity</code> — always <code>&quot;customers&quot;</code> for this report.</li><li><code>type</code> — echoes back the requested panel.</li><li><code>dateRange</code> — an <strong>object</strong> <code>{ previous, current }</code>, where each value is a human-readable label for the corresponding window (e.g. <code>&quot;10 May 2026 - 09 Jun 2026&quot;</code>).</li><li><code>statistics</code> — an object or array whose shape depends on <code>type</code> (documented below).</li></ul><h2 id="response-shapes-by-type" tabindex="-1">Response shapes by <code>type</code> <a class="header-anchor" href="#response-shapes-by-type" aria-label="Permalink to &quot;Response shapes by `type`&quot;">​</a></h2><p>Figures with a <code>previous</code> / <code>current</code> / <code>progress</code> shape are period comparisons: <code>current</code> is the chosen window, <code>previous</code> is the preceding window of equal length, and <code>progress</code> is the percentage change (can be negative).</p><h3 id="total-customers" tabindex="-1"><code>total-customers</code> <a class="header-anchor" href="#total-customers" aria-label="Permalink to &quot;`total-customers`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>customers</code></td><td><code>{ previous, current, progress }</code></td><td>New customers registered.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{ label, total }], current: [{ label, total }] }</code></td><td>Two series — previous and current windows — one bucket per day for the chart line.</td></tr></tbody></table><h3 id="customers-traffic" tabindex="-1"><code>customers-traffic</code> <a class="header-anchor" href="#customers-traffic" aria-label="Permalink to &quot;`customers-traffic`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>total</code></td><td><code>{ previous, current, progress }</code></td><td>All customer visits.</td></tr><tr><td><code>unique</code></td><td><code>{ previous, current, progress }</code></td><td>Unique customer visits.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{ label, total }], current: [{ label, total }] }</code></td><td>Two daily series for the chart.</td></tr></tbody></table><p>This panel is chart-only — there is <strong>no View Details / Export</strong> table for <code>customers-traffic</code>. Traffic figures depend on the Bagisto visitor/analytics tables being populated; on a fresh store the totals are <code>0</code> and the <code>over_time</code> series are empty.</p><h3 id="customers-with-most-sales" tabindex="-1"><code>customers-with-most-sales</code> <a class="header-anchor" href="#customers-with-most-sales" aria-label="Permalink to &quot;`customers-with-most-sales`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong>. Each row: <code>id</code> (may be <code>null</code> for guest checkouts), <code>email</code>, <code>full_name</code>, <code>total</code>, <code>orders</code>, <code>progress</code>, <code>formatted_total</code>.</p><h3 id="customers-with-most-orders" tabindex="-1"><code>customers-with-most-orders</code> <a class="header-anchor" href="#customers-with-most-orders" aria-label="Permalink to &quot;`customers-with-most-orders`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong>. Each row: <code>id</code> (may be <code>null</code> for guest checkouts), <code>email</code>, <code>full_name</code>, <code>orders</code>, <code>progress</code>.</p><h3 id="customers-with-most-reviews" tabindex="-1"><code>customers-with-most-reviews</code> <a class="header-anchor" href="#customers-with-most-reviews" aria-label="Permalink to &quot;`customers-with-most-reviews`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong>. Each row: <code>id</code> (may be <code>null</code> for guest reviews), <code>email</code>, <code>full_name</code>, <code>reviews</code>, <code>progress</code>.</p><h3 id="top-customer-groups" tabindex="-1"><code>top-customer-groups</code> <a class="header-anchor" href="#top-customer-groups" aria-label="Permalink to &quot;`top-customer-groups`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong>. Each row: <code>id</code>, <code>group_name</code>, <code>total</code>, <code>progress</code>.</p><h2 id="view-details" tabindex="-1">View Details <a class="header-anchor" href="#view-details" aria-label="Permalink to &quot;View Details&quot;">​</a></h2><p><code>GET /api/admin/reporting/customers/view</code> returns the same statistics as the summary <code>stats</code> endpoint, but in a detailed table form — the full list that sits behind a panel&#39;s <strong>View Details</strong> link. It honors the same <code>?type=</code> parameter. The <code>statistics</code> object carries:</p><ul><li><code>columns</code> — an ordered list of <code>{ key, label }</code> describing each table column.</li><li><code>records</code> — the row data, each keyed by the column <code>key</code> values (records may carry extra fields beyond the displayed columns).</li></ul><p>The table columns per <code>type</code>:</p><table tabindex="0"><thead><tr><th><code>type</code></th><th><code>columns</code> (<code>key</code>)</th></tr></thead><tbody><tr><td><code>total-customers</code></td><td><code>label</code>, <code>total</code></td></tr><tr><td><code>customers-with-most-sales</code></td><td><code>full_name</code>, <code>email</code>, <code>formatted_total</code></td></tr><tr><td><code>customers-with-most-orders</code></td><td><code>full_name</code>, <code>email</code>, <code>orders</code></td></tr><tr><td><code>customers-with-most-reviews</code></td><td><code>full_name</code>, <code>email</code>, <code>reviews</code></td></tr><tr><td><code>top-customer-groups</code></td><td><code>group_name</code>, <code>total</code></td></tr></tbody></table><p><code>customers-traffic</code> is chart-only and has no table form.</p><h2 id="export-csv" tabindex="-1">Export (CSV) <a class="header-anchor" href="#export-csv" aria-label="Permalink to &quot;Export (CSV)&quot;">​</a></h2><p><code>GET /api/admin/reporting/customers/export</code> streams the same detailed table as a <code>text/csv</code> attachment (the <strong>Export</strong> button). It honors the same <code>?type=</code>. The header row is built from the column labels, followed by one line per record. Send <code>Accept: text/csv</code> and save the response to a file.</p><p>Only <code>?format=csv</code> is accepted — any other <code>format</code> value returns HTTP 422.</p><p>Both <strong>View Details</strong> and <strong>Export</strong> require only authentication; reporting has no permission gate.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>HTTP</th><th>Body</th></tr></thead><tbody><tr><td>Missing / invalid Bearer token</td><td><code>401</code></td><td><code>{ &quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot; }</code></td></tr><tr><td>Unknown <code>type</code> value</td><td><code>400</code></td><td><code>{ ... &quot;Invalid reporting stat type.&quot; }</code></td></tr><tr><td><code>format</code> other than <code>csv</code> on Export</td><td><code>422</code></td><td><code>{ ... &quot;Unsupported export format.&quot; }</code></td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/api/graphql-api/admin/reporting/customers.html">Reporting — Customers (GraphQL)</a> — same data over the <code>statsAdminReportingCustomers</code> query.</li><li><a href="/api/rest-api/admin/reporting/">Reporting</a> — the sales, customers and products report endpoints.</li></ul>',45)]))}const h=t(a,[["render",n]]);export{m as __pageData,h as default};
